<section class="page-heading small-heading"><div class="site-width"><a class="breadcrumb" href="<?= e(url('lesson?id='.$lesson['id'])) ?>">← Tagasi õppetundi</a><span class="section-label">TEADMISTE KONTROLL</span><h1><?= e($lesson['title']) ?></h1><p>Vali igale küsimusele üks õige vastus.</p></div></section><section class="site-width quiz-wrap">
<?php if (!$questions): ?><div class="empty-state">Selle õppetunni test ei ole veel valmis. <a href="<?= e(url('lesson?id='.$lesson['id'])) ?>">Tagasi õppetundi</a></div>
<?php elseif ($result !== null): ?><div class="result-card"><div class="result-icon" aria-hidden="true">✓</div><span class="section-label">TEST ON TEHTUD</span><h2>Sinu tulemus: <?= (int)$result['correct'] ?> / <?= (int)$result['total'] ?></h2><p><?= (int)round($result['correct']/$result['total']*100) ?>% vastustest oli õiged.</p><p class="muted"><?= is_logged_in()?'Tulemus on sinu õpiteel salvestatud.':'Logi sisse, et tulevased tulemused oma õpiteele salvestada.' ?></p><div class="quiz-feedback"><h3>Vastuste ülevaade</h3><?php foreach ($feedback as $item): ?><div class="feedback-item <?= $item['correct']?'feedback-correct':'feedback-incorrect' ?>"><strong><?= $item['correct']?'✓ Õige vastus':'✕ Vale vastus' ?></strong><p><?= e($item['question']) ?></p><p>Õige vastus: <b><?= e($item['answer']) ?></b></p></div><?php endforeach; ?></div><div class="result-actions"><a class="btn btn-primary" href="<?= e(url('quiz?id='.$lesson['id'])) ?>">Proovi uuesti</a><a class="btn btn-outline" href="<?= e(url('lesson?id='.$lesson['id'])) ?>">Tagasi õppetundi</a></div></div>
<?php else: ?><form method="post" action="<?= e(url('quiz')) ?>"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="lesson_id" value="<?= (int)$lesson['id'] ?>"><?php foreach ($questions as $i=>$question): ?><fieldset class="question-card"><legend><span class="question-number"><?= $i+1 ?> / <?= count($questions) ?></span><?= e($question['question']) ?></legend><div class="answer-list"><?php foreach ($question['options'] as $option): ?><label class="answer-option"><input type="radio" name="answer[<?= (int)$question['id'] ?>]" value="<?= (int)$option['id'] ?>" required><span><?= e($option['option_text']) ?></span></label><?php endforeach; ?></div></fieldset><?php endforeach; ?><button class="btn btn-primary btn-large" type="submit">Kontrolli vastuseid <span aria-hidden="true">→</span></button></form><?php endif; ?></section>
